#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main(void) {
    long long N, K, S;
    if (scanf("%lld %lld %lld", &N, &K, &S) != 3) return 0;

    long long minStep = K;
    long long maxStep = K * N;

    /* If even one jump cannot move at all, impossible unless S==0.
       But values are from 1..N, so minStep>=1 always for valid constraints. */

    if (S == 0) {
        printf("0\n");
        return 0;
    }

    /* Reachability:
       After t jumps, total distance is sum of t independent jump lengths,
       each in [K, K*N]. Thus possible totals are exactly all integers in
       [t*K, t*K*N] (contiguous because each jump sum itself can be any integer
       in [K, K*N]).
       So S is reachable iff there exists integer t with:
           t*K <= S <= t*K*N
       which is equivalent to:
           ceil(S/(K*N)) <= floor(S/K)
    */
    long long tmin = (S + maxStep - 1) / maxStep;  // ceil(S / maxStep)
    long long tmax = S / minStep;                  // floor(S / minStep)

    if (tmin > tmax) {
        printf("-1\n");
        return 0;
    }

    /* Let X be one-jump distance. We need expected number of jumps to hit S
       for the first time exactly. Since all increments are positive, "first hit S"
       is same as "ever hit S".

       Define f[x] = probability of ever hitting exactly total x starting from 0.
       Then:
           f[0] = 1
           f[x] = sum_{d} P(X=d) * f[x-d]   for x>=1, with f[neg]=0

       The expected number of attacks over all time equals sum_x P(hit at time x?)?
       More directly, if p_t = P(sum after t jumps = S), then because sums strictly
       increase, events over t are disjoint and:
           P(ever hit S) = sum_t p_t = f[S].

       The expected jump count conditioned/unconditioned on first attack:
           E[T ; hit] = sum_t t * p_t.
       If P(hit)<1, then expected number of jumps to first attack is impossible
       (there is positive probability of never attacking), so output -1.
       If P(hit)=1, then E[T] is finite because T <= floor(S/K).

       So we need to determine whether f[S]=1. For a finite positive-step random walk,
       this happens iff every state up to S is surely hittable, which in this DAG
       recurrence means all support steps must force eventual hit. Practically,
       because there can be overshoot, f[S] < 1 unless all possible paths from 0
       reach S before exceeding it.

       Since jumps are positive and bounded, hitting S with probability 1 occurs
       exactly when for every reachable x<S and every possible step d in support,
       either x+d<=S and remains in a sure-hit state, and no step overshoots S.
       This is equivalent to maxStep <= remaining distance at every reachable state,
       which can only happen in deterministic case.

       More simply:
       - If jump length is deterministic (only one possible value D), then hit is
         certain iff S is divisible by D, and answer is S/D.
       - Otherwise there are at least two possible jump lengths, causing from some
         reachable state before S a chance to overshoot or miss forever, hence hit
         probability < 1, so expected value is unbounded -> -1.

       Here one-jump distance is sum of K iid uniform 1..N.
       This distribution is deterministic iff N==1 (then each generated integer is 1,
       so every jump is exactly K).
    */

    if (N != 1) {
        printf("-1\n");
        return 0;
    }

    /* Deterministic jump size = K */
    if (S % K != 0) {
        printf("-1\n");
        return 0;
    }

    printf("%.10f\n", (double)(S / K));
    return 0;
}

import java.util.Scanner;

public class WitchJump {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int S = sc.nextInt();
        sc.close();

        if (S == 0) {
            System.out.println("0.0");
            return;
        }

        // Check if reachable
        int g = N;
        for (int i = 1; i <= N; i++) {
            g = gcd(g, i);
        }
        if (S % g != 0) {
            System.out.println("-1");
            return;
        }

        double[] E = new double[S + 1];
        E[0] = 0.0;

        for (int x = 1; x <= S; x++) {
            double sum = 0.0;
            int cnt = 0;
            for (int d = 1; d <= N; d++) {
                if (x - d >= 0) {
                    sum += E[x - d];
                    cnt++;
                }
            }
            if (cnt == N) {
                // E[x] = 1 + (1/N) * sum
                E[x] = 1.0 + sum / N;
            } else {
                // Some moves overshoot, those count as reaching 0 in 1 step from this position
                // E[x] = 1 + (1/N)*(sum of E[0..x-1] + (N-cnt)*0)
                E[x] = 1.0 + sum / N;
            }
        }

        System.out.printf("%.15f%n", E[S]);
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

