public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return Math.abs(a);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long N = fs.nextLong();
        long K = fs.nextLong();
        long S = fs.nextLong();

        long minStep = K;
        long maxStep = K * N;

        // If S cannot be represented as a sum of some number of jump-sums:
        // each jump contributes an integer in [K, KN].
        // Reachable totals after t jumps form all integers in [tK, tKN].
        // Therefore S is reachable iff there exists integer t with tK <= S <= tKN,
        // i.e. ceil(S/(KN)) <= floor(S/K).
        if ((S + maxStep - 1) / maxStep > S / minStep) {
            System.out.println(-1);
            return;
        }

        // Special deterministic case: each jump length is always K (thus N=1).
        // Then the number of jumps is fixed if reachable.
        if (N == 1) {
            if (S % K != 0) System.out.println(-1);
            else System.out.println((double)(S / K));
            return;
        }

        // Let X be one-jump progress, support in [K, KN], mean mu = K(N+1)/2.
        // We stop at first time T such that cumulative sum equals S.
        //
        // For lattice renewal processes with positive increments, E[T_hit(S)] is finite
        // iff the target is reachable and the process can hit exactly with probability 1.
        // Here because overshooting is possible and increments are strictly positive,
        // exact hit probability is < 1 whenever there is more than one possible jump size.
        // Therefore the unconditional expected value is infinite, so answer is -1.
        //
        // More concretely, since N>1, each jump has at least two possible lengths.
        // For sufficiently large reachable S, there are paths that overshoot before hitting,
        // giving positive probability of never hitting exactly. Hence expected jumps is unbounded.
